B.ag1={"restricted-exhaust-airflow":0,"clogged-lint-pathway":1,"thermal-fuse-open":2,"accessible-thermal-reset":3,"motor-overheat-protector-open":4,"heating-element-failed":5,"electric-supply-connection-fault":6,"broken-drive-belt":7,"worn-drum-rollers":8,"idler-pulley-wear":9,"door-switch-failure":10,"motor-failure":11}
B.ZS=s([u._,u.c,u.a,"Unplug the dryer (or switch off its breaker) before moving it.","Restore power, run a short heat cycle, and re-check exterior airflow."],t.s)
B.pm=s([B.mI,B.rt],t.c)
B.Sp=new A.cb("restricted-exhaust-airflow",u.z,u.h0,B.ZS,B.j,B.pm,B.a0,!0,!0)
B.a0m=s(["Unplug the dryer before inspecting the lint housing.","Clean the lint filter and any safely accessible lint around the slot.","Do not dismantle sealed cabinets or wiring.","Restore power and run a small test load on a heat cycle."],t.s)
B.a0B=s([B.mI,B.rz],t.c)
B.Sw=new A.cb("clogged-lint-pathway",u.gS,u.cR,B.a0m,B.j,B.a0B,B.a0,!0,!0)
